select g.game_id, g.team_id, g.goalie_id, g.starter_probability, round(g.proj_saves,1) sv, jsonb_array_length(g.uncertainty->'goalie_candidates') cands, (select round(sum((c->>'start_probability')::numeric),3) from jsonb_array_elements(g.uncertainty->'goalie_candidates') c) cand_sum, left((g.uncertainty->'goalie_candidates'->0)::text,300) c0 from forge_goalie_projections g where g.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9'
